package com.morphlabs.morph.core.academy.deck

import com.morphlabs.morph.core.academy.Action
import com.morphlabs.morph.core.academy.Card
import com.morphlabs.morph.core.academy.Signal
import com.morphlabs.morph.core.academy.Track

internal object ProtectionCards {
    private val T = Track.PROTECTION
    val cards: List<Card> = listOf(
        // ---------- Level 1: Rookie ----------
        quiz("pr-insurance-what", T, 1, "What is insurance, at its heart?",
            listOf("Many people pay small premiums to cover the few who suffer big losses", "A savings account that pays interest", "A loan you repay after an accident", "A government grant for emergencies"), 0,
            "It is like a big chama for bad luck: everyone chips in, and the unlucky few get paid. You swap a small certain cost for protection from a large uncertain one.",
            source = "IRA"),
        concept("pr-terms", T, 1, "What do premium, cover and excess mean?",
            "Premium: what you pay for the policy. Cover (sum insured): the most the insurer will pay. Excess: the part of each claim you pay yourself before the insurer pays the rest.",
            source = "IRA"),
        quiz("pr-excess", T, 1, "Your car repair costs Ksh 80,000 and your policy excess is Ksh 20,000. The insurer pays:",
            listOf("Ksh 60,000", "Ksh 80,000", "Ksh 20,000", "Ksh 100,000"), 0,
            "You pay the first Ksh 20,000 (the excess); the insurer covers the remaining Ksh 60,000, up to your policy limits.",
            source = "IRA"),
        concept("pr-ef-self-insure", T, 1, "Why is an emergency fund called \"self-insurance\"?",
            "It pays for small shocks yourself: a phone repair, a clinic visit, a week without work. No premiums, no claim forms. Save insurance for big losses you could never cover alone.",
            tryThis = "Open a separate pot just for emergencies", action = Action.ACCOUNTS,
            signals = setOf(Signal.NO_EMERGENCY_FUND)),
        quiz("pr-fake-mpesa", T, 1, "You get an SMS saying you received Ksh 5,000. How do you confirm it's real?",
            listOf("Check your M-Pesa balance or statement", "Trust it if it looks official", "Call the number that sent it", "Reply to the SMS"), 0,
            "Fake messages are typed to look like M-Pesa. Only your actual balance proves money arrived. Real M-Pesa messages come from \"MPESA\", not a phone number.",
            source = "Safaricom"),
        concept("pr-wrong-number", T, 1, "Someone calls: \"I sent you money by mistake, please send it back.\" What do you do?",
            "Check your balance first. If no money came in, it's a scam. If it did, don't send it yourself; tell them to call Safaricom to reverse it. Forward the scam SMS to 333.",
            source = "Safaricom"),
        quiz("pr-pin", T, 1, "Who is allowed to ask for your M-Pesa PIN?",
            listOf("Nobody, not even Safaricom", "Safaricom customer care", "An M-Pesa agent", "Your bank"), 0,
            "Safaricom says never share your PIN with anyone. Its staff call only from 0722 000 000 and will never ask for your PIN.",
            source = "Safaricom, 2026"),
        concept("pr-sim-swap", T, 1, "Your phone suddenly shows \"No network\" for no reason. Why could that be dangerous?",
            "It can be a SIM swap: a fraudster got your number moved to their SIM to receive your codes and empty your M-Pesa or bank. Call 100 or 200 from another phone right away.",
            source = "Safaricom"),
        quiz("pr-fake-job", T, 1, "A \"recruiter\" offers you a job abroad but asks for a Ksh 15,000 processing fee first. Red flag?",
            listOf("Yes: real jobs rarely ask you to pay to be hired", "No, all agencies charge this", "Only if they don't send a letter", "Only if the job is local"), 0,
            "Fake job offers collect fees then vanish. Verify any foreign recruitment agency with the National Employment Authority before paying.",
            source = "National Employment Authority"),
        quiz("pr-333", T, 1, "Where do you forward a suspicious M-Pesa SMS so Safaricom can block the sender?",
            listOf("333", "100", "456", "911"), 0,
            "Forwarding to 333 helps Safaricom block the number so others aren't scammed. You can also call 100 or 200.",
            source = "Safaricom"),
        concept("pr-red-flags", T, 1, "Name four red flags of a scam.",
            "1) Guaranteed high returns. 2) Pressure to act now. 3) Requests for your PIN, OTP or a fee upfront. 4) Being told to keep it secret or recruit friends. Any one is a reason to stop.",
            source = "CMA investor alerts"),
        quiz("pr-what-to-insure", T, 1, "Which risk is most worth insuring?",
            listOf("A hospital stay that could cost Ksh 300,000", "A cracked phone screen", "Losing a Ksh 500 umbrella", "A late matatu"), 0,
            "Insure what would wreck you financially. Small, likely losses are cheaper to cover from your own emergency fund.",
            source = "Basic insurance principles"),

        // ---------- Level 2: Hustler ----------
        you("pr-you-ef", T, 2, "Your emergency target is {emergency_target} and you have {savings}. What shock could you absorb today?",
            "Compare the two. If {savings} is below {emergency_target}, a job loss or hospital bill could push you to Fuliza or loans. Each small top-up buys you time and choice.",
            tryThis = "Set a weekly auto-save towards your emergency target", action = Action.BUDGETS,
            signals = setOf(Signal.NO_EMERGENCY_FUND)),
        quiz("pr-excess-tradeoff", T, 2, "You choose a higher excess on your car policy. What normally happens to your premium?",
            listOf("It goes down", "It goes up", "It stays the same", "It doubles"), 0,
            "You agree to carry more of each loss, so the insurer charges less. It works if your emergency fund can pay that excess.",
            source = "IRA"),
        concept("pr-average-clause", T, 2, "What is underinsurance and the \"average\" clause?",
            "If you insure property for less than it's worth, many policies pay only the same share of a loss. Insure a Ksh 4M house for Ksh 2M (half), and a Ksh 1M fire loss pays only Ksh 500,000.",
            source = "IRA consumer guide"),
        quiz("pr-average-quiz", T, 2, "Shop stock worth Ksh 1M is insured for Ksh 500,000. A theft costs Ksh 200,000. With an average clause you get:",
            listOf("Ksh 100,000", "Ksh 200,000", "Ksh 500,000", "Nothing"), 0,
            "You insured half the value, so the insurer pays half of the loss. Update your sum insured as stock grows.",
            source = "IRA consumer guide"),
        quiz("pr-fuliza-scam", T, 2, "An SMS says \"Your Fuliza limit has been raised, click here to activate.\" Best move?",
            listOf("Ignore the link and check Fuliza via *234# or the M-Pesa app", "Click quickly before it expires", "Reply with your ID number", "Call the number in the SMS"), 0,
            "Safaricom lists fake Fuliza limit messages among top scams. Check only through official channels and forward the SMS to 333.",
            source = "Safaricom, 2026", signals = setOf(Signal.FULIZA_RECENT)),
        quiz("pr-otp", T, 2, "A caller says they're from your bank and asks you to read out a code just sent by SMS. You:",
            listOf("Refuse and hang up: the code unlocks your account", "Read it, banks need it", "Read half of it", "Send it by SMS instead"), 0,
            "A one-time code (OTP) is a key. Anyone who has it can approve transfers or a SIM swap. No real bank asks for it.",
            source = "CBK consumer advisories"),
        concept("pr-ponzi-vs-business", T, 2, "How do you tell a Ponzi scheme from a real business?",
            "A real business earns from customers. A Ponzi pays old investors with new investors' money. If you can't explain where returns come from, or returns depend on recruiting, walk away.",
            source = "CMA; US SEC"),
        quiz("pr-insure-small", T, 2, "Why is insuring small, likely losses (like a cheap phone) often poor value?",
            listOf("Premiums cover expected claims plus costs and profit", "Insurers never pay small claims", "It is illegal", "Small items can't be insured"), 0,
            "On average you pay more than you get back. Insurance earns its keep on rare, large losses you couldn't absorb.",
            source = "Basic insurance principles"),
        concept("pr-claim-steps", T, 2, "What helps a claim get paid quickly?",
            "Report fast, within the policy's deadline. For theft or a road accident get a police abstract. Take photos, keep receipts, and get claim numbers in writing.",
            source = "IRA"),
        quiz("pr-check-licence", T, 2, "How can you check an insurance company or agent is genuine?",
            listOf("Look them up on the IRA's licensed list", "Check their Facebook likes", "Ask for a business card", "See if their office looks big"), 0,
            "The Insurance Regulatory Authority publishes licensed insurers, brokers and agents. Unlicensed sellers may take premiums and never pay claims.",
            source = "IRA"),
        concept("pr-phone-lock", T, 2, "Three quick ways to lock down your phone money?",
            "1) Use a screen lock and different PINs for M-Pesa, SIM and bank apps. 2) Never share OTPs. 3) Don't save PINs in notes or SMS. A stolen unlocked phone is an open wallet.",
            source = "Safaricom fraud awareness"),

        // ---------- Level 3: Pro ----------
        quiz("pr-sha-replace", T, 3, "Which scheme replaced NHIF as Kenya's national health insurance in October 2024?",
            listOf("SHIF, run by the Social Health Authority (SHA)", "NSSF Health", "Linda Mama", "The Housing Levy fund"), 0,
            "The Social Health Insurance Act 2023 created SHA, which took over from NHIF on 1 October 2024.",
            source = "Social Health Insurance Act 2023"),
        quiz("pr-shif-calc", T, 3, "Your gross pay is Ksh 50,000 a month. Your SHIF deduction at 2.75% is:",
            listOf("Ksh 1,375", "Ksh 500", "Ksh 1,700", "Ksh 2,750"), 0,
            "50,000 x 2.75% = Ksh 1,375. There is no upper cap, unlike NHIF's old Ksh 1,700 maximum, so higher earners pay more.",
            source = "SHA, 2026", timeSensitive = true),
        concept("pr-shif-min", T, 3, "What do people without a payslip pay for SHIF?",
            "2.75% of household income as assessed by SHA's means test, with a minimum of Ksh 300 a month. Late payment can attract penalties and interrupt cover.",
            source = "SHA, 2026", timeSensitive = true),
        concept("pr-sha-funds", T, 3, "What are SHA's three funds?",
            "Primary Healthcare Fund (government-funded, community and lower-level care), SHIF (your contributions, hospital care), and the Emergency, Chronic and Critical Illness Fund (kicks in when SHIF benefits run out).",
            source = "Social Health Insurance Act 2023"),
        quiz("pr-term-vs-whole", T, 3, "How does term life insurance differ from whole life?",
            listOf("Term covers a set period, is cheaper, and has no savings value", "Term costs more and builds savings", "Whole life only covers accidents", "They are identical"), 0,
            "Term pays out only if you die within, say, 20 years. Whole life covers you for life and builds a cash value, so premiums are much higher.",
            source = "IRA"),
        concept("pr-term-tradeoff", T, 3, "What's the trade-off between term cover plus investing, and a savings-linked life policy?",
            "Term is cheap pure protection; you invest the difference yourself, with more flexibility but discipline needed. Savings policies force saving but often carry higher fees and penalties if you stop early.",
            source = "IRA consumer education"),
        concept("pr-life-cover-size", T, 3, "Who needs life cover, and roughly how much?",
            "Anyone with people depending on their income. A common rule of thumb is about 10 times yearly income, adjusted for debts, school fees and savings. No dependants? You may need little.",
            source = "Industry rule of thumb"),
        quiz("pr-motor-tp", T, 3, "Third-party motor cover pays for what?",
            listOf("Injury or damage you cause to others, not your own car", "Everything, including your car", "Only theft of your car", "Only your own medical bills"), 0,
            "Third-party cover is the legal minimum for any vehicle on Kenyan roads. Comprehensive adds damage to and theft of your own car.",
            source = "Insurance (Motor Vehicles Third Party Risks) Act, Cap 405"),
        concept("pr-motor-comp", T, 3, "When does comprehensive motor cover make sense?",
            "When the car is worth more than you could replace from savings, or it's on a loan (lenders usually require it). For an old, cheap car, third-party plus your own savings may be enough.",
            source = "IRA"),
        quiz("pr-deci", T, 3, "Kenya's 2007 pyramid scheme collapse, led by DECI, cost investors roughly how much?",
            listOf("About Ksh 8 billion across 270+ schemes", "About Ksh 8 million", "About Ksh 800 billion", "Nothing; all were repaid"), 0,
            "DECI alone took about Ksh 2.4bn from around 93,000 people. Few were ever prosecuted, and most savers never got their money back.",
            source = "Nation; The Standard"),
        quiz("pr-cbex", T, 3, "CBEX, which collapsed in April 2025, lured Kenyans by promising what?",
            listOf("100% returns in 30 days via \"AI trading\"", "A 5% yearly bank deposit", "Free land in Konza", "Government bonds at 12%"), 0,
            "Balances went to zero overnight. Some victims had borrowed to invest. The CMA issued an alert on unregulated platforms.",
            source = "Business Daily; CMA, 2025"),
        concept("pr-forex-scam", T, 3, "How do forex \"account manager\" scams work, and how do you check a broker?",
            "Someone on WhatsApp or Telegram offers to trade for you and shows fake profits, then asks for \"withdrawal fees\". Real online forex brokers must be licensed by the CMA; check its list first.",
            source = "CMA"),

        // ---------- Level 4: Shark ----------
        quiz("pr-will-valid", T, 4, "Under Kenya's Law of Succession Act, a valid written will must be:",
            listOf("Signed by you and attested by at least two competent witnesses", "Stamped by a chief", "Registered with KRA", "Read aloud in court"), 0,
            "Section 11 sets the rule. Courts have struck down wills with only one proper witness, leaving the estate to be shared as if there were no will.",
            source = "Law of Succession Act, Cap 160, s.11"),
        quiz("pr-intestacy", T, 4, "A man dies without a will, leaving a wife and children. Under s.35, the widow gets:",
            listOf("Household effects plus a life interest in the rest", "Nothing; it all goes to the children", "Exactly half of everything", "Everything outright"), 0,
            "She owns personal and household effects; the rest she holds for life, then it passes to the children. Selling capital usually needs their or the court's consent.",
            source = "Law of Succession Act, s.35"),
        concept("pr-intestacy-pain", T, 4, "Why is dying without a will costly for a family?",
            "Accounts, land and shares can be frozen until the court issues a grant of letters of administration. That can take months or years, and disputes often follow. A will plus listed assets saves time and fights.",
            source = "Law of Succession Act, Cap 160"),
        quiz("pr-sacco-nominee", T, 4, "A SACCO member dies with a named nominee. What happens to their deposits?",
            listOf("They go to the nominee, after any loan balance is set off", "They go into the estate for court", "The SACCO keeps them", "They go to the government"), 0,
            "Courts have held that nominated deposits go to the nominee directly. Outstanding loans can be deducted first.",
            source = "Co-operative Societies Act; Kenya Law, 2023"),
        concept("pr-pension-nominee", T, 4, "Why name beneficiaries on your pension scheme?",
            "Death benefits from a retirement scheme are paid out by its trustees, who use your nomination as a guide. Keeping it updated (new spouse, new child) helps the right people get paid faster.",
            source = "Retirement Benefits Authority", tryThis = "Check who is nominated on your pension and SACCO accounts"),
        quiz("pr-pcf", T, 4, "If an insurer collapses, the Policyholders Compensation Fund now pays up to how much per claim?",
            listOf("Ksh 500,000", "Ksh 50,000", "Ksh 5 million", "The full claim, no limit"), 0,
            "The limit doubled from Ksh 250,000 from January 2026. Bigger claims may get only part of what's owed, so the insurer's strength matters.",
            source = "National Treasury; PCF, 2026", timeSensitive = true),
        concept("pr-ira-complaints", T, 4, "Your insurer keeps delaying a valid claim. What can you do?",
            "Escalate in writing to the insurer's complaints desk and keep records. If unresolved, lodge a complaint with the Insurance Regulatory Authority, which supervises insurers and can follow up.",
            source = "IRA"),
        quiz("pr-dpa-fine", T, 4, "Under the Data Protection Act 2019, the maximum administrative fine for a company is:",
            listOf("Ksh 5M or 1% of annual turnover, whichever is lower", "Ksh 50,000 flat", "10% of profits", "Unlimited"), 0,
            "The Data Commissioner has fined firms the full Ksh 5M, including Oppo Kenya and a digital lender.",
            source = "Data Protection Act 2019; ODPC"),
        concept("pr-dpa-rights", T, 4, "What rights do you have over your personal data in Kenya?",
            "To be told how it's used, to access it, to correct it, to have it deleted, and to object to its use. If a loan app shames you to your contacts, complain to the Office of the Data Protection Commissioner.",
            source = "Data Protection Act 2019, s.26"),
        quiz("pr-wiba", T, 4, "Which insurance must every Kenyan employer have for staff?",
            listOf("Work injury cover under WIBA", "Comprehensive motor cover", "Key person life cover", "Business interruption cover"), 0,
            "The Work Injury Benefits Act 2007 requires employers to insure workers for injury and occupational disease at work.",
            source = "Work Injury Benefits Act 2007"),
        concept("pr-business-cover", T, 4, "What insurance does a small business typically consider?",
            "Fire and property (premises and stock), theft, public liability (a customer slips), business interruption (lost income after a fire), WIBA for staff, and key person cover if one founder drives everything.",
            source = "IRA; AKI"),
        quiz("pr-vasp", T, 4, "Kenya's Virtual Asset Service Providers Act 2025 says crypto platforms will be licensed by:",
            listOf("CBK and CMA", "KRA only", "Safaricom", "No one: crypto is banned"), 0,
            "The law took effect in November 2025. Licensing awaits regulations, so no crypto platform held a Kenyan licence as of late 2025.",
            source = "CBK public notice, 2025", timeSensitive = true),

        // ---------- Level 5: Legend ----------
        concept("pr-pooling", T, 5, "Why can an insurer predict claims when you can't predict your own?",
            "The law of large numbers. Your chance of a fire is uncertain, but across 100,000 homes the share that burn each year is stable. Pooling turns individual chaos into predictable averages.",
            source = "Bernoulli; actuarial science"),
        quiz("pr-adverse-selection", T, 5, "\"Adverse selection\" in insurance means:",
            listOf("Riskier people are more likely to buy cover", "Insurers reject everyone risky", "Customers pick the cheapest plan", "Claims are paid late"), 0,
            "If only the sick join, premiums rise, healthy people leave, and the pool spirals. Akerlof (1970) and Rothschild & Stiglitz (1976) modelled this.",
            source = "Akerlof, 1970; Rothschild & Stiglitz, 1976"),
        quiz("pr-moral-hazard", T, 5, "\"Moral hazard\" means:",
            listOf("Being insured makes people take less care", "Insurers lying about cover", "Paying premiums late", "Buying too many policies"), 0,
            "Arrow (1963) and Pauly (1968) analysed it. Excesses and co-pays exist partly to keep you sharing some of the cost.",
            source = "Arrow, 1963; Pauly, 1968"),
        concept("pr-mandate", T, 5, "Why is SHIF compulsory rather than optional?",
            "To beat adverse selection. If joining were voluntary, mostly sick people would join and premiums would spiral. A mandate pools the healthy with the sick, so cover is affordable.",
            source = "WHO; health economics"),
        quiz("pr-index-insurance", T, 5, "Index insurance pays out based on what?",
            listOf("A measured index like rainfall, not an inspected loss", "Each farmer's own receipts", "A vote by the chama", "The insurer's profits"), 0,
            "No loss adjusters, so it's cheap to run and can't be gamed by farmers. The catch is basis risk.",
            source = "World Bank"),
        concept("pr-basis-risk", T, 5, "What is basis risk?",
            "The gap between the index and your actual loss. The weather station shows enough rain, but your shamba dried up: no payout. It's a big reason farmers distrust index products.",
            source = "World Bank; ILRI"),
        quiz("pr-kilimo-salama", T, 5, "Kilimo Salama (2009) brought weather insurance to Kenyan farmers. How did it pay out?",
            listOf("Via M-Pesa, based on local weather station rainfall", "In cash at the chief's office", "As free seed the next year", "Through NHIF"), 0,
            "Built by the Syngenta Foundation with UAP and Safaricom. Farmers paid a 5% premium on seed and fertiliser. It grew into ACRE Africa.",
            source = "World Bank; Syngenta Foundation"),
        concept("pr-ibli", T, 5, "How does Index-Based Livestock Insurance (IBLI) in Marsabit work?",
            "Launched in January 2010 by ILRI and partners, it uses satellite pasture data to estimate herd losses. First payouts went to about 650 herders in October 2011 during drought.",
            source = "ILRI; Cornell, 2011"),
        quiz("pr-karlan-ghana", T, 5, "Karlan et al. (2014) gave Ghanaian farmers rain insurance. Main finding?",
            listOf("Insured farmers invested more in their farms", "Insurance made farmers lazy", "No one bought it at any price", "Cash grants beat everything"), 0,
            "Risk, not just lack of credit, held back farm investment. Removing the downside let farmers spend more on inputs.",
            source = "Karlan, Osei, Osei-Akoto & Udry, QJE, 2014"),
        concept("pr-demand-puzzle", T, 5, "Why do so few smallholders buy index insurance, even when it seems useful?",
            "Cole et al. (2013) in India found demand very sensitive to price, trust in the provider and liquidity. Basis risk and unfamiliarity also hurt. Bundling with credit or inputs helps.",
            source = "Cole et al., AEJ: Applied, 2013"),
        concept("pr-failed-insurers", T, 5, "Which Kenyan insurers have failed recently?",
            "Resolution (2022) and Xplico (Dec 2023) went into statutory management; Invesco was liquidated in 2023. In March 2026 the IRA placed Trident, KUSCCO Mutual and Corporate Insurance under statutory management.",
            source = "IRA; PCF, 2026", timeSensitive = true),
        quiz("pr-kuscco", T, 5, "Auditors found what at KUSCCO, the SACCO umbrella body, in 2025?",
            listOf("A hole of roughly Ksh 12–13 billion", "A surplus of Ksh 13 billion", "No irregularities", "A small Ksh 13 million gap"), 0,
            "Falsified accounts, fund diversion and insider loans. Member SACCOs lost deposits. Diversify and read your SACCO's audited accounts.",
            source = "Kenyans.co.ke; Business Daily, 2025"),
        quiz("pr-madoff", T, 5, "What was the giveaway in Bernie Madoff's Ponzi, exposed in 2008?",
            listOf("Returns that were too smooth, year after year", "Very high but volatile returns", "A tiny client list", "Heavy advertising"), 0,
            "He reported steady ~10% gains in good and bad markets. Fake statements hid about USD 65 billion in paper losses.",
            source = "US SEC Inspector General, 2009"),
    )
}
